#!/usr/bin/env python3
"""Closed external-provider fixture. No outbound HTTP client or forwarding path.
Only exact named fixtures are accepted; request bodies/credentials are never logged.
"""
import argparse, base64, hashlib, http.server, json, pathlib, re, threading, time

class Fixture:
    def __init__(self, marker, dimensions, photo):
        if not re.fullmatch(r'dvportion-[a-f0-9]{12}', marker):
            raise ValueError('Use dvportion- plus 12 lowercase hex digits')
        if not 1 <= dimensions <= 10000:
            raise ValueError('Invalid explicit embedding dimensions')
        self.marker, self.dimensions, self.photo = marker, dimensions, photo
        self.photo_hash = hashlib.sha256(photo).hexdigest()
        self.pasta, self.sauce = marker + ' pasta', marker + ' sauce'
        self.name = 'DV portions fixture ' + marker
        self.recipe = {'@context':'https://schema.org','@type':'Recipe','name':self.name,
            'description':'Deterministic external-provider DV acceptance fixture.', 'recipeYield':'4 servings',
            'recipeIngredient':['200 g '+self.pasta, '100 ml '+self.sauce],
            'supply':[{'name':self.pasta,'requiredQuantity':{'value':200,'unitText':'g'}},
                      {'name':self.sauce,'requiredQuantity':{'value':100,'unitText':'ml'}}],
            'recipeInstructions':[{'text':'Add half of the '+self.pasta+' (100 g).'}, {'text':'Simmer 20 minutes at 180 °C.'}]}
        self.html = ('<!doctype html><html lang="en"><title>'+self.name+'</title><body><h1>'+self.name+
            '</h1><p>4 servings</p><ul><li>200 g '+self.pasta+'</li><li>100 ml '+self.sauce+
            '</li></ul><p>Add half of the '+self.pasta+' (100 g).</p><p>Simmer 20 minutes at 180 °C.</p></body></html>').encode()

    def chat(self, body):
        messages = body.get('messages')
        if not isinstance(messages, list) or body.get('stream'):
            raise ValueError('Only nonstreaming fixture chats are supported')
        texts, images = [], []
        for message in messages:
            content = message.get('content', '')
            if isinstance(content, str):
                texts.append(content)
            elif isinstance(content, list):
                for part in content:
                    if part.get('type') == 'text': texts.append(part.get('text',''))
                    elif part.get('type') == 'image_url': images.append(part.get('image_url',{}).get('url',''))
                    else: raise ValueError('Unsupported message content')
            else: raise ValueError('Unsupported message content')
        text = '\n'.join(texts)
        image_fixture = False
        if images:
            if len(images) != 1 or not images[0].startswith('data:image/png;base64,'):
                raise ValueError('Unrecognized photo fixture')
            try: image_bytes = base64.b64decode(images[0].split(',',1)[1], validate=True)
            except Exception: raise ValueError('Invalid photo bytes')
            if hashlib.sha256(image_bytes).hexdigest() != self.photo_hash:
                raise ValueError('Unrecognized photo fixture')
            image_fixture = True
        if self.marker not in text and not image_fixture:
            raise ValueError('Nonfixture request rejected')
        if 'You are an objective food writer.' in text and 'Recipe Data (JSON):\n' in text:
            recipe = json.loads(text.split('Recipe Data (JSON):\n',1)[1].strip())
            if recipe.get('name') != self.name or recipe.get('recipeIngredient') != self.recipe['recipeIngredient']:
                raise ValueError('Nonfixture description request rejected')
            return 'description', 'Half of the pasta is used with an explicit numeric annotation alongside sauce.'
        if 'Extract from this HTML:' in text and self.html.decode() in text:
            return 'web-context', {'name':self.name,'heroImageUrl':None,'notes':None}
        if 'Please extract the recipe as instructed.' in text and (image_fixture or self.html.decode() in text):
            return 'extraction', self.recipe
        if 'You are a grocery categorization assistant.' in text and 'Input:\n' in text:
            request = json.loads(text.rsplit('Input:\n',1)[1].strip())
            ingredients = request.get('ingredients')
            if not isinstance(ingredients,list) or not ingredients or any(name not in [self.pasta,self.sauce] for name in ingredients):
                raise ValueError('Nonfixture grocery request rejected')
            return 'ingredient-category', [{'normalizedKey':name,'section':'Pantry','confidence':1.0} for name in ingredients]
        if 'Recipe Name: '+self.name in text and '"primaryMealType"' in text and self.pasta in text:
            return 'recipe-category', {'cuisineType':'Italian','mealTypes':['Lunch','Supper'],'primaryMealType':'Lunch','isVegetarian':True}
        raise ValueError('Unknown fixture task rejected')

    def embedding(self, body):
        text = '\n'.join(part.get('text','') for part in body.get('content',{}).get('parts',[]))
        if self.marker not in text or self.pasta not in text:
            raise ValueError('Nonfixture embedding rejected')
        if body.get('outputDimensionality') != self.dimensions:
            raise ValueError('Embedding dimension does not match configured acceptance identity')
        return {'embedding':{'values':[1.0]+[0.0]*(self.dimensions-1)}}


def main():
    parser=argparse.ArgumentParser()
    parser.add_argument('--marker', default='dvportion-8c508f3f3173')
    parser.add_argument('--dimensions',type=int,required=True)
    parser.add_argument('--host',default='127.0.0.1')
    parser.add_argument('--port',type=int,default=3493)
    parser.add_argument('--audit',type=pathlib.Path,default=pathlib.Path(__file__).with_name('requests.ndjson'))
    parser.add_argument('--self-test',action='store_true')
    args=parser.parse_args()
    fixture=Fixture(args.marker,args.dimensions,pathlib.Path(__file__).with_name('photo.png').read_bytes())
    if args.self_test:
        def chat(text): return {'messages':[{'role':'user','content':text}]}
        assert fixture.chat(chat('Extract from this HTML:\n\n'+fixture.html.decode()))[0]=='web-context'
        assert fixture.chat(chat('Please extract the recipe as instructed.\nSOURCE HTML:\n'+fixture.html.decode()))[1]==fixture.recipe
        photo={'messages':[{'role':'user','content':[{'type':'text','text':'Please extract the recipe as instructed.'},{'type':'image_url','image_url':{'url':'data:image/png;base64,'+base64.b64encode(fixture.photo).decode()}}]}]}
        assert fixture.chat(photo)[0]=='extraction'
        description='You are an objective food writer.\nRecipe Data (JSON):\n'+json.dumps(fixture.recipe)
        assert fixture.chat(chat(description))[0]=='description'
        wrong_description=description.replace(fixture.name, 'Unrelated recipe')
        try: fixture.chat(chat(wrong_description))
        except ValueError: pass
        else: raise AssertionError('Nonfixture description accepted')
        category='You are a grocery categorization assistant.\nInput:\n'+json.dumps({'ingredients':[fixture.pasta,fixture.sauce]})
        assert fixture.chat(chat(category))[0]=='ingredient-category'
        assert fixture.chat(chat('Recipe Name: '+fixture.name+'\n"primaryMealType"\n'+fixture.pasta))[0]=='recipe-category'
        assert len(fixture.embedding({'content':{'parts':[{'text':fixture.pasta}]},'outputDimensionality':args.dimensions})['embedding']['values'])==args.dimensions
        for body in [chat('Unrelated household recipe'),chat(args.marker+' but unknown task')]:
            try: fixture.chat(body)
            except ValueError: pass
            else: raise AssertionError('Nonfixture accepted')
        print(json.dumps({'selfTest':'passed','marker':args.marker,'dimensions':args.dimensions,'realProviderCalls':0}))
        return
    lock=threading.Lock()
    def audit(path,status,kind):
        with lock, args.audit.open('a') as out:
            out.write(json.dumps({'utc':time.time(),'path':path,'status':status,'kind':kind})+'\n')
    class Handler(http.server.BaseHTTPRequestHandler):
        def log_message(self,*args): pass
        def reply(self,status,value,kind,content_type='application/json'):
            raw=value if isinstance(value,bytes) else json.dumps(value).encode()
            self.send_response(status);self.send_header('Content-Type',content_type);self.send_header('Content-Length',str(len(raw)));self.end_headers();self.wfile.write(raw)
            audit(self.path,status,kind)
        def do_GET(self):
            if self.path=='/health': self.reply(200,{'fixture':args.marker,'dimensions':args.dimensions,'outbound':False},'health')
            elif self.path=='/fixtures/'+args.marker+'/recipe.html': self.reply(200,fixture.html,'source-html','text/html; charset=utf-8')
            elif self.path=='/fixtures/'+args.marker+'/photo.png': self.reply(200,fixture.photo,'source-photo','image/png')
            else: self.reply(404,{'error':{'message':'Unknown fixture route','type':'fixture_rejected'}},'rejected')
        def do_POST(self):
            try:
                length=int(self.headers.get('Content-Length','0'))
                if length<=0 or length>3_000_000: raise ValueError('Unsupported request size')
                body=json.loads(self.rfile.read(length))
                if self.path=='/v1beta/openai/chat/completions':
                    kind,result=fixture.chat(body)
                    self.reply(200,{'id':'chatcmpl-'+args.marker,'object':'chat.completion','created':int(time.time()),'model':body.get('model','fixture'),
                        'choices':[{'index':0,'message':{'role':'assistant','content':result if isinstance(result,str) else json.dumps(result)},'finish_reason':'stop'}],
                        'usage':{'prompt_tokens':1,'completion_tokens':1,'total_tokens':2}},kind)
                elif re.fullmatch(r'/v1beta/models/[^/]+:embedContent',self.path): self.reply(200,fixture.embedding(body),'embedding')
                else: self.reply(404,{'error':{'message':'Unknown provider route','type':'fixture_rejected'}},'rejected')
            except (ValueError,TypeError,KeyError,AttributeError): self.reply(422,{'error':{'message':'Closed fixture rejected request','type':'fixture_rejected'}},'rejected')
    print(json.dumps({'listen':args.host+':'+str(args.port),'marker':args.marker,'dimensions':args.dimensions,'photoSha256':fixture.photo_hash,'outbound':False}),flush=True)
    http.server.ThreadingHTTPServer((args.host,args.port),Handler).serve_forever()

if __name__=='__main__': main()
